// The Cloudflare Worker entry: OpenNext's Next.js handler, plus the daily cron that Vercel Cron runs on Vercel
// (vercel.json). The cron calls the app's own route with the same Bearer CRON_SECRET header Vercel sends.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import handler from "../.open-next/worker.js";

interface Env {
  CRON_SECRET?: string;
  PINPLAN_APP_URL?: string;
}

/**
 * A ceiling for every /api/* request body, checked on the declared Content-Length before Next.js runs. The largest
 * legitimate body (photos for the AI daily summary, base64) is well under it. Routes open to the public read their
 * bodies through src/lib/server/readBody.ts with much tighter limits, which also stop a body sent without a length.
 */
const MAX_API_BODY_BYTES = 20 * 1024 * 1024;

function tooLarge(request: Request): boolean {
  if (request.method === "GET" || request.method === "HEAD") return false;
  if (!new URL(request.url).pathname.startsWith("/api/")) return false;
  const len = request.headers.get("content-length");
  return len != null && /^\d+$/.test(len.trim()) && Number(len.trim()) > MAX_API_BODY_BYTES;
}

export default {
  fetch(request: Request, env: unknown, ctx: unknown) {
    if (tooLarge(request))
      return Response.json({ error: "The request is too large.", code: "payload_too_large" }, { status: 413, headers: { "Cache-Control": "no-store" } });
    return handler.fetch(request, env, ctx);
  },

  async scheduled(_event: unknown, env: Env, ctx: { waitUntil(p: Promise<unknown>): void }) {
    if (!env.CRON_SECRET) {
      console.warn("[cron] CRON_SECRET is not set: billing reminders skipped");
      return;
    }
    const base = (env.PINPLAN_APP_URL || "https://localhost").replace(/\/+$/, "");
    const request = new Request(`${base}/api/cron/billing-reminders`, { headers: { authorization: `Bearer ${env.CRON_SECRET}` } });
    ctx.waitUntil(
      handler.fetch(request, env, ctx).then(async (r: Response) => {
        if (!r.ok) console.error("[cron] billing reminders failed", r.status, (await r.text()).slice(0, 300));
      }),
    );
  },
};
